import json,sys,base64,re
d=json.loads(json.load(open(sys.argv[1]))['result'])
lim=int(sys.argv[2]) if len(sys.argv)>2 else 2500
def walk(p):
    out=[]
    if p.get('mimeType','').startswith('text/plain') and p.get('body',{}).get('data'):
        out.append(base64.urlsafe_b64decode(p['body']['data']+'==').decode('utf8','replace'))
    for c in p.get('parts',[]) or []: out+=walk(c)
    return out
for m in d['messages']:
  h={x['name']:x['value'] for x in m['payload'].get('headers',[])}
  b='\n'.join(walk(m['payload']))
  if not b:
    hb=[]
    def w2(p):
      if p.get('mimeType')=='text/html' and p.get('body',{}).get('data'): hb.append(re.sub('<[^>]+>',' ',base64.urlsafe_b64decode(p['body']['data']+'==').decode('utf8','replace')))
      for c in p.get('parts',[]) or []: w2(c)
    w2(m['payload']); b='\n'.join(hb)
  print('=====',h.get('Date'),'|',h.get('From'),'| To:',h.get('To'),'| Cc:',h.get('Cc'),'|',h.get('Subject'))
  print(re.sub(r'\n\s*\n+','\n',b)[:lim])
EOF
